import{_ as t,o as a,c as s,ag as r}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"CS [2xxx] Building Apps with AI","description":"","frontmatter":{"source":"SYLLABUS.md"},"headers":[],"relativePath":"SYLLABUS.md","filePath":"SYLLABUS.md"}'),o={name:"SYLLABUS.md"};function i(n,e,d,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="cs-2xxx-building-apps-with-ai" tabindex="-1">CS [2xxx] Building Apps with AI <a class="header-anchor" href="#cs-2xxx-building-apps-with-ai" aria-label="Permalink to &quot;CS [2xxx] Building Apps with AI&quot;">​</a></h1><p>3 credits</p><p>[Semester and year, as scheduled]</p><h2 id="instructor" tabindex="-1">Instructor <a class="header-anchor" href="#instructor" aria-label="Permalink to &quot;Instructor&quot;">​</a></h2><ul><li><strong>Name:</strong> [name]</li><li><strong>Email:</strong> [email]</li><li><strong>Phone:</strong> [phone]</li><li><strong>Office hours:</strong> [days, times and place]</li><li><strong>Class meetings:</strong> [days, times and room]; two 75-minute studios a week, Studio A (Learn &amp; build) and Studio B (Workshop)</li></ul><p>Email response time: normally within 24 hours on weekdays, possibly longer over weekends and holidays.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>One programming course in any language, such as CS 1112, CS 1120, CS 2120 or another department&#39;s programming course; equivalent programming experience; or instructor permission. No experience with web development, the terminal or git is needed, and <a href="./setup/python-to-javascript.html">From Python to JavaScript</a> covers what changes for students who know Python. CS students who have completed CS 3383 Software Engineering should take <a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/" target="_blank" rel="noreferrer">Engineering Software with AI</a> (CS [4xxx]/[5xxx]) instead.</p><h2 id="course-description" tabindex="-1">Course Description <a class="header-anchor" href="#course-description" aria-label="Permalink to &quot;Course Description&quot;">​</a></h2><p>This course teaches students from any major to build and ship web apps by directing AI tools, and to apply the engineering habits that make AI-written software trustworthy. Topics include how large language models write code; HTML, CSS and JavaScript; prompting; version control with git and GitHub; specifications with testable acceptance criteria; automated testing; reading and debugging code; APIs, servers and secret keys; AI agents and code review through pull requests; database access rules; web security; and deployment. Students learn by building, in two hands-on studios a week. They begin with a chat assistant and finish with an AI agent working in their own repository, shipping a series of projects to the public web with free tools and ending with a capstone of their own choosing. The course introduces vibe coding and its limits, and it emphasizes writing the specification before the prompt, checking AI output, protecting secrets and data, and being able to explain every line of code without AI.</p><h2 id="required-textbooks-and-materials" tabindex="-1">Required Textbooks and Materials <a class="header-anchor" href="#required-textbooks-and-materials" aria-label="Permalink to &quot;Required Textbooks and Materials&quot;">​</a></h2><p>No textbook. Students need a laptop with a modern browser and several free accounts; the required cost is $0 (<a href="./TOOLS.html">Tool Handout</a> lists every tool and its free fallbacks). Before the first class, students complete the <a href="./setup/#before-studio-1">first-hour quick start</a>, which takes 60 to 90 minutes.</p><h2 id="learning-outcomes" tabindex="-1">Learning Outcomes <a class="header-anchor" href="#learning-outcomes" aria-label="Permalink to &quot;Learning Outcomes&quot;">​</a></h2><p>At the end of this course, students will be able to:</p><ul><li>Build working web software, from single-file pages to a full-stack app, by directing chat assistants, app builders and coding agents through a repeatable workflow (the <a href="./resources/safe-loop.html">Safe Loop</a>), and switch to a fallback tool without losing work.</li><li>Develop a one-page specification with user stories and testable acceptance criteria before building.</li><li>Evaluate AI output rather than trust it: write the check first, test normal and edge cases, and read the diff.</li><li>Explain every part of the code they submit, and debug a failing program by reading its error messages, without AI.</li><li>Apply version control with git and GitHub as a safety net, committing, comparing, reverting, branching and reviewing changes through pull requests.</li><li>Deploy projects to the public web and present them clearly while protecting privacy and secrets, which includes keeping API keys on the server, enforcing database access rules, checking dependencies and containing AI agents.</li></ul><h2 id="course-outline" tabindex="-1">Course Outline <a class="header-anchor" href="#course-outline" aria-label="Permalink to &quot;Course Outline&quot;">​</a></h2><p>The course follows a standard 16-week semester. Weeks 1–15 have two studios a week; week 16 is finals week, when the <a href="./weeks/16-project-fair/project-fair.html">Project Fair</a> takes place in the scheduled two-hour final exam slot.</p><table tabindex="0"><thead><tr><th>Week</th><th>Topic</th><th>Key concepts</th></tr></thead><tbody><tr><td>1</td><td><a href="./weeks/01-hello-vibe-coding/">Hello, Vibe Coding</a></td><td>Vibe coding and its limits; how an LLM writes code; what a web page is (HTML, CSS, JavaScript); the AI-use labels; privacy settings and the safety contract</td></tr><tr><td>2</td><td><a href="./weeks/02-ship-your-page/">Ship Your Page</a></td><td>Publishing on GitHub Pages; commits as save points; what a public repository exposes; three prompting habits; accessibility from the start; <code>PROMPTS.md</code>; personal AI-use rules</td></tr><tr><td>3</td><td><a href="./weeks/03-prompting-and-save-points/">Prompting &amp; Save Points</a></td><td>Prompts as directions (goal, context, constraints, done when); the context window; small steps and the two-strikes rule; commits; <code>Assisted-by:</code> lines</td></tr><tr><td>4</td><td><a href="./weeks/04-undo-compare-explain/">Undo, Compare, Explain</a></td><td>Rolling back to a save point; comparing two models against a written check; explaining code you did not write; rewriting weak prompts; a first automated test</td></tr><tr><td>5</td><td><a href="./weeks/05-spec-first/">Spec First</a></td><td>The spec as the prompt for the whole project; user stories and priorities; testable acceptance criteria; out of scope; the Goldfish test; app builders</td></tr><tr><td>6</td><td><a href="./weeks/06-spec-to-app/">From Spec to App</a></td><td>Judging apps against written criteria; app-builder lock-in and credits; rules in a module of pure functions; writing the test first; previewing before you commit</td></tr><tr><td>7</td><td><a href="./weeks/07-read-and-debug/">Read It, Debug It</a></td><td>Anatomy of a web app; reading error messages and stack traces; a debugging method (reproduce, isolate, hypothesize, test, fix, verify); edge cases</td></tr><tr><td>8</td><td><a href="./weeks/08-own-it/">Own It</a></td><td>Git history as a debugging tool (<code>log</code>, <code>diff</code>, <code>revert</code>); writing code by hand while the AI reviews; testing the project&#39;s logic; oral walkthrough 1</td></tr><tr><td>9</td><td><a href="./weeks/09-apis-and-secrets/">APIs &amp; Secrets</a></td><td>Requests, responses and APIs; the browser is public; API keys kept on the server; checking every input on the server; the system prompt as product design</td></tr><tr><td>10</td><td><a href="./weeks/10-servers-and-deployment/">Servers &amp; Deployment</a></td><td>Serverless functions; deploying to a production URL; one API format, many providers; proving the key stays secret; revoking a leaked key; calling public APIs</td></tr><tr><td>11</td><td><a href="./weeks/11-agents/">How Agents Work</a></td><td>An agent as an LLM in a loop with tools; context as working memory; plans, approvals and sandboxes; how agents fail; <code>AGENTS.md</code>; credits as a budget</td></tr><tr><td>12</td><td><a href="./weeks/12-pull-requests/">Pull Requests &amp; Agent Code</a></td><td>Branches and pull requests; reviewing agent code that is almost right; checking changes to the tests; testing your instructions; chart and external-API features; oral walkthrough 2</td></tr><tr><td>13</td><td><a href="./weeks/13-data-and-access/">Data &amp; Access Rules</a></td><td>Authentication versus authorization; Supabase; grants and row-level security (RLS); attacking a practice table; recent data leaks</td></tr><tr><td>14</td><td><a href="./weeks/14-security-and-review/">Security &amp; Review</a></td><td>Cross-site scripting; secrets in git history; risky packages; prompt injection; a one-paragraph threat model; changing one&#39;s own code with the AI off; human and AI review; oral walkthrough 3</td></tr><tr><td>15</td><td><a href="./weeks/15-ship-it/">Ship It</a></td><td>The definition of done; polish; accessibility; honest known issues; a demo video; where the field is going; ethics, law and disclosure</td></tr><tr><td>16</td><td><a href="./weeks/16-project-fair/">Project Fair</a> (finals week)</td><td>The Project Fair in the final exam slot; a <code>v1.0</code> release; feedback from real users; felt versus actual understanding; revising personal AI-use rules</td></tr></tbody></table><h2 id="evaluation-procedures" tabindex="-1">Evaluation Procedures <a class="header-anchor" href="#evaluation-procedures" aria-label="Permalink to &quot;Evaluation Procedures&quot;">​</a></h2><h3 id="assessment" tabindex="-1">Assessment <a class="header-anchor" href="#assessment" aria-label="Permalink to &quot;Assessment&quot;">​</a></h3><p>Grades are based on evidence of process and understanding as well as on whether a program runs. Weekly labs, timed builds and exit tickets are graded on effort and completion rather than correctness.</p><table tabindex="0"><thead><tr><th>Component</th><th>Weight</th></tr></thead><tbody><tr><td>Weekly labs and homework</td><td>20%</td></tr><tr><td>In-class builds, exit tickets and participation</td><td>15%</td></tr><tr><td>Project 1</td><td>10%</td></tr><tr><td>Capstone</td><td>30%</td></tr><tr><td>Oral walkthroughs (weeks 8, 12, 14)</td><td>15%</td></tr><tr><td>AI-free reflections and peer reviews</td><td>10%</td></tr></tbody></table><p>The <a href="./assessment/">assessment guide</a> is part of this syllabus. It contains the rubrics, the conversion of points to a grade, the dropped scores and retakes, and the rules on <a href="./assessment/#absences-and-make-up-work">attendance, absences and make-up work</a>. Each of the <a href="./resources/without-ai-skills.html">six skills students must show without AI</a> must be shown at least once, in an oral walkthrough, a retake or a short follow-up.</p><h3 id="final-examination" tabindex="-1">Final Examination <a class="header-anchor" href="#final-examination" aria-label="Permalink to &quot;Final Examination&quot;">​</a></h3><p>There is no written final examination. In week 16, the <a href="./weeks/16-project-fair/project-fair.html">Project Fair</a> takes place in the course&#39;s scheduled two-hour final exam slot and is scored like a studio. Students present their capstones in a gallery walk, try one another&#39;s apps and leave feedback, and complete the post-course self-assessment without AI. The capstone&#39;s final product (the production URL with a screenshot, the <code>v1.0</code> release and the demo video) is due at the start of the Fair. The final reflection and the revised personal AI-use rules are due at 11:59 pm on the last day of finals week.</p><h3 id="performance-standards-and-grading-policy" tabindex="-1">Performance Standards and Grading Policy <a class="header-anchor" href="#performance-standards-and-grading-policy" aria-label="Permalink to &quot;Performance Standards and Grading Policy&quot;">​</a></h3><p>Letter grades are A (90–100%), B (80–89%), C (70–79%), D (60–69%) and F (below 60%). A grade of C or higher also requires a capstone that works at its production URL, all three oral walkthroughs, and each of the six skills shown without AI at least once (<a href="./assessment/#letter-grades">details</a>).</p><h3 id="assignments" tabindex="-1">Assignments <a class="header-anchor" href="#assignments" aria-label="Permalink to &quot;Assignments&quot;">​</a></h3><ul><li>Weekly labs and homework (weeks 1–15), including the <a href="./projects/home-page.html">home page</a> and its game in weeks 1–4 and the <a href="./projects/ai-micro-app.html">AI micro-app</a> with the capstone pitch in weeks 9–10. Homework is due before the next week&#39;s Studio A unless Canvas states otherwise. Students who fall behind should complete each week&#39;s &quot;Minimum to keep up&quot; section first.</li><li>In-class work and exit tickets: lab work, peer explanation and checkpoints in every studio, and a short exit ticket, written without AI, in weeks 1–14.</li><li>Projects: <a href="./projects/project-1-useful-tool.html">Project 1, A Tool I&#39;d Actually Use</a> (weeks 5–8), and the <a href="./projects/capstone.html">capstone</a> (weeks 11–16), a deployed full-stack app of the student&#39;s choice built with an AI agent, individually or in a pair. Every project repository keeps a <code>PROMPTS.md</code> log of how AI was used. Briefs, project rules and submission steps are in the <a href="./projects/">projects guide</a>. A student whose Project 1 is not working by week 7 may continue from a <a href="./projects/rescue-starters/">rescue starter</a>.</li><li>Oral walkthroughs in weeks 8, 12 and 14: ten-minute conversations without AI in which students explain their code, change it live and find a planted bug (<a href="./assessment/oral-walkthroughs.html">protocol</a>).</li><li>Reflections and peer reviews: weekly reflections, two written peer reviews and a final reflection, all written without AI.</li></ul><p>Graded personal writing, including reflections, peer reviews, exit tickets, self-assessments and personal AI-use rules, is submitted on Canvas, the course&#39;s learning management system, and never placed in a repository (<a href="./assessment/#privacy-of-your-work">privacy of your work</a>).</p><h3 id="late-work-policy" tabindex="-1">Late Work Policy <a class="header-anchor" href="#late-work-policy" aria-label="Permalink to &quot;Late Work Policy&quot;">​</a></h3><p>Each student has two grace tokens; each extends one deadline by 48 hours, with no reason required. Beyond that, late work loses 10% of its points per day for up to three days and then scores zero unless an extension has been agreed. Tokens do not apply to live events (studios, exit tickets, oral walkthroughs and the Project Fair), which have their own <a href="./assessment/#absences-and-make-up-work">make-up rules</a>. Running out of free AI credits does not by itself justify a late submission, because switching to a fallback tool is part of the course. The full rules are under <a href="./assessment/#late-work-and-grace-tokens">late work and grace tokens</a>.</p><h2 id="ai-use" tabindex="-1">AI Use <a class="header-anchor" href="#ai-use" aria-label="Permalink to &quot;AI Use&quot;">​</a></h2><p>AI tools are a required part of this course. Grades depend on whether students can explain the work they submit; the amount of AI they used does not matter. Every task carries one of three labels: AI on, AI limited or AI off. Exit tickets, oral walkthroughs, reflections, written peer reviews, self-assessments and personal AI-use rules are always AI off. Students are responsible for understanding, validating and explaining all work they submit, and may be asked to explain any line of it. AI help is disclosed in each project&#39;s <code>PROMPTS.md</code> log and in an <code>Assisted-by: [tool]</code> line on AI-assisted commits. The complete lists of AI-limited and AI-off work are in the <a href="./assessment/#ai-use-policy">AI use policy</a>, and the rules for working safely with AI tools are in the <a href="./setup/safety-contract.html">safety contract</a>.</p><h2 id="academic-honesty" tabindex="-1">Academic Honesty <a class="header-anchor" href="#academic-honesty" aria-label="Permalink to &quot;Academic Honesty&quot;">​</a></h2><p>Academic honesty is important at the University of Idaho because it is the way you improve over time. Academic dishonesty, which includes cheating and plagiarism, is not tolerated at the University of Idaho.</p><p>Plagiarism means claiming another&#39;s work as your own. That can happen in several ways:</p><ul><li>Copying another&#39;s work in whole or in part</li><li>Quoting another&#39;s work without attribution</li><li>Paraphrasing another&#39;s work without attribution</li><li>Purchasing another&#39;s work from &quot;study aid&quot; websites</li></ul><p>In this course it also includes using AI where a task is marked AI off, and hiding AI help that the <a href="#ai-use">AI Use</a> rules ask you to disclose. Suspected academic dishonesty is handled under the University&#39;s Student Code of Conduct and Resolution Process (FSH 2300), which includes reporting it to the Dean of Students. If you have any questions about how to cite a source or credit an AI tool, please ask me.</p><h2 id="university-of-idaho-classroom-learning-civility-clause" tabindex="-1">University of Idaho Classroom Learning Civility Clause <a class="header-anchor" href="#university-of-idaho-classroom-learning-civility-clause" aria-label="Permalink to &quot;University of Idaho Classroom Learning Civility Clause&quot;">​</a></h2><p>In any environment in which people gather to learn, it is essential that all members feel as free and safe as possible in their participation. To this end, it is expected that everyone in this course will be treated with mutual respect and civility, with an understanding that all of us (students, instructors, professors, guests, and teaching assistants) will be respectful and civil to one another in discussion, in action, in teaching, and in learning.</p><p>Should you feel our classroom interactions do not reflect an environment of civility and respect, you are encouraged to meet with your instructor during office hours to discuss your concern. Additional resources for expression of concern or requesting support include the <a href="https://www.uidaho.edu/student-resources/dean-of-students" target="_blank" rel="noreferrer">Dean of Students</a> office and staff, the UI <a href="https://www.uidaho.edu/student-resources/health-wellness/counseling-mental-health-center" target="_blank" rel="noreferrer">Counseling and Mental Health Center</a>, or the UI <a href="https://www.uidaho.edu/civil-rights" target="_blank" rel="noreferrer">Office of Civil Rights and Investigations</a>.</p><h2 id="center-for-disability-access-and-resources" tabindex="-1">Center for Disability Access and Resources <a class="header-anchor" href="#center-for-disability-access-and-resources" aria-label="Permalink to &quot;Center for Disability Access and Resources&quot;">​</a></h2><p>University of Idaho&#39;s Center for Disability Access and Resources recommends that faculty and instructors include on all syllabi a statement informing students with disabilities of their right to request reasonable accommodations in the classroom.</p><p>Center for Disability Access and Resources (CDAR) coordinates services to meet the educational needs of students with temporary or permanent disabilities. CDAR works with students and faculty to arrange reasonable accommodations and promote an environment that is inclusive for all learners.</p><p>Students with disabilities needing accommodations to fully participate in this class should contact the Center for Disability Access and Resources (CDAR). All accommodations must be approved through CDAR prior to being implemented. To learn more about the accommodation process, visit CDAR&#39;s website at <a href="https://www.uidaho.edu/cdar" target="_blank" rel="noreferrer">www.uidaho.edu/cdar</a> or call 208-885-6307.</p><h2 id="firearms" tabindex="-1">Firearms <a class="header-anchor" href="#firearms" aria-label="Permalink to &quot;Firearms&quot;">​</a></h2><p>The University of Idaho bans firearms from its property with only limited exceptions. One exception applies to persons who hold a valid Idaho enhanced concealed carry license, provided those firearms remain concealed at all times. If an enhanced concealed carry license holder&#39;s firearm is displayed, other than in necessary self-defense, it is a violation of University policy. Please contact local law enforcement (call 911) to report firearms on University property. University of Idaho leadership remains committed to maintaining a safe work, living and learning environment on campus. We will not tolerate any threatening use of firearms or any other weapons. While authorized license holders may have familiarity and be at ease carrying a loaded firearm, we ask that they be aware that many people are not familiar with handguns and are uncomfortable in their presence.</p><h2 id="student-resources" tabindex="-1">Student Resources <a class="header-anchor" href="#student-resources" aria-label="Permalink to &quot;Student Resources&quot;">​</a></h2><p>The University of Idaho provides student support to ensure a successful learning experience: <a href="https://www.uidaho.edu/student-resources" target="_blank" rel="noreferrer">UofI Student Resources</a>.</p><ul><li><strong>SI-PASS (Peer Assisted Study Sessions):</strong> regularly scheduled, peer-led study sessions for difficult courses (<a href="https://www.uidaho.edu/student-resources/academic-support/peer-assisted-study-sessions" target="_blank" rel="noreferrer">SI-PASS</a>).</li><li><strong>Library help:</strong> the <a href="https://www.lib.uidaho.edu/" target="_blank" rel="noreferrer">UofI Library website</a> has many databases that will help you find relevant and reliable books, articles, images, and more. Don&#39;t hesitate to contact a librarian for research assistance.</li><li><strong>Technology help:</strong> the OIT <a href="https://www.uidaho.edu/student-resources/technical-support" target="_blank" rel="noreferrer">IT Service Desk</a> provides technology-related services to students. Phone: 208-885-HELP (208-885-4357). Requests: <a href="https://support.uidaho.edu/" target="_blank" rel="noreferrer">support.uidaho.edu</a>.</li><li><strong>Writing support:</strong> the <a href="https://www.uidaho.edu/student-resources/academic-support/writing-center" target="_blank" rel="noreferrer">UofI Writing Center</a> provides one-on-one assistance to student writers and other members of the campus community. Phone: 208-885-6644.</li><li><strong>Student Success Program (SSP):</strong> in-house resources specifically for students living in the residence halls. Academic Peer Mentors provide free tutoring and academic support Sundays–Thursdays from 2:00 pm to 10:00 pm. SSP is located in the Wallace Residence Center basement. Students do not need to live in the Wallace Residence Center to use this resource.</li><li><strong>Vandal Food Pantry:</strong> a <a href="https://www.uidaho.edu/student-resources/dean-of-students/basic-needs-food-insecurity-resources" target="_blank" rel="noreferrer">free resource</a> stocked weekly with food, grocery bags, and various hygiene items, open to all. Please take what you need.</li><li><strong>Green Dot Safety Program:</strong> Vandal Green Dot helps students learn about the power of the bystander, how to recognize potentially risky situations, and realistic ways to intervene. Learn more and get involved through the UI <a href="https://www.uidaho.edu/student-resources/health-wellness/violence-prevention-center" target="_blank" rel="noreferrer">Green Dot Safety Program</a> or by emailing <a href="mailto:greendot@uidaho.edu" target="_blank" rel="noreferrer">greendot@uidaho.edu</a>.</li></ul><h2 id="uofi-moscow-land-acknowledgement" tabindex="-1">UofI Moscow Land Acknowledgement <a class="header-anchor" href="#uofi-moscow-land-acknowledgement" aria-label="Permalink to &quot;UofI Moscow Land Acknowledgement&quot;">​</a></h2><p>UofI Moscow is located on the homelands of the Nimiipuu (Nez Perce), Palus (Palouse) and Schitsu&#39;umsh (Coeur d&#39;Alene) tribes. We extend gratitude to the indigenous people that call this place home, since time immemorial. UofI recognizes that it is our academic responsibility to build relationships with the indigenous people to ensure integrity of tribal voices.</p>',53)])])}const f=t(o,[["render",i]]);export{p as __pageData,f as default};
